package com.bonbio.service;
import com.bonbio.dto.Dtos.*; import com.bonbio.entity.Categorie; import com.bonbio.repository.CategorieRepository; import com.bonbio.repository.ProduitRepository; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import java.util.List;
@Service public class CategorieService { private final CategorieRepository repo; private final ProduitRepository produits; public CategorieService(CategorieRepository repo,ProduitRepository produits){this.repo=repo;this.produits=produits;} public List<CategorieResponse> all(){return repo.findAll().stream().map(this::out).toList();} public CategorieResponse one(Long id){return out(repo.findById(id).orElseThrow(()->new RuntimeException("Catégorie introuvable.")));} @Transactional(readOnly=true) public List<ProduitResponse> products(Long id){repo.findById(id).orElseThrow(()->new RuntimeException("Catégorie introuvable."));return produits.findByCategorieId(id).stream().map(p->new ProduitResponse(p.getId(),p.getNom(),p.getPrix(),p.getPhotoUrl(),p.getDescription(),new CategorieResponse(p.getCategorie().getId(),p.getCategorie().getNom()))).toList();} public CategorieResponse save(Long id,CategorieRequest r){Categorie c=id==null?new Categorie():repo.findById(id).orElseThrow(()->new RuntimeException("Catégorie introuvable."));c.setNom(r.nom());return out(repo.save(c));} @Transactional public void delete(Long id){Categorie c=repo.findById(id).orElseThrow(()->new RuntimeException("Catégorie introuvable."));if(produits.countByCategorieId(id)>0)throw new IllegalStateException("Cette catégorie contient encore des produits. Veuillez déplacer ou supprimer ces produits avant de supprimer la catégorie.");repo.delete(c);} private CategorieResponse out(Categorie c){return new CategorieResponse(c.getId(),c.getNom());} }
